// RF experimental propio: bootstrap + submuestreo de variables + árboles CART.
export const CONFIG={trees:40,maxDepth:5,minLeaf:6,maxFeatures:2,seed:2025};
export const FEATURES=['Tmax t','Tmax t−1','Media Tmax 7 días','Lluvia t','Lluvia 7 días'];
const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;
const valid=v=>typeof v==='number'&&Number.isFinite(v)&&v!==-999;
export function features(window){if(window.length!==7||window.some(r=>!valid(r.temp)||!valid(r.rain)||r.rain<0))return null;for(let i=1;i<7;i++)if(Date.parse(window[i].date)-Date.parse(window[i-1].date)!==86400000)return null;return [window[6].temp,window[5].temp,mean(window.map(r=>r.temp)),window[6].rain,window.reduce((s,r)=>s+r.rain,0)];}
export function dataset(rows){const sorted=[...rows].sort((a,b)=>a.date.localeCompare(b.date));const seen=new Set();for(const r of sorted){if(!/^2025-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date||seen.has(r.date))throw Error('Fechas inválidas, duplicadas o fuera de 2025');seen.add(r.date);}const samples=[];for(let i=6;i<sorted.length-1;i++){const next=sorted[i+1],x=features(sorted.slice(i-6,i+1));if(x&&valid(next.temp)&&Date.parse(next.date)-Date.parse(sorted[i].date)===86400000)samples.push({x,y:next.temp,date:next.date,origin:sorted[i].date});}return {sorted,samples};}
function rng(seed){return ()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};}
const sse=items=>{const m=mean(items.map(r=>r.y));return items.reduce((s,r)=>s+(r.y-m)**2,0);};
export function train(samples,config=CONFIG){const random=rng(config.seed),importance=Array(5).fill(0);
 function tree(items,depth){const value=mean(items.map(r=>r.y));if(depth>=config.maxDepth||items.length<2*config.minLeaf)return {value};let candidates=[0,1,2,3,4];for(let i=4;i>0;i--){const j=Math.floor(random()*(i+1));[candidates[i],candidates[j]]=[candidates[j],candidates[i]];}let best=null,bestLoss=sse(items);const parentLoss=bestLoss;
 for(const f of candidates.slice(0,config.maxFeatures)){const ordered=[...items].sort((a,b)=>a.x[f]-b.x[f]);for(let j=config.minLeaf;j<=ordered.length-config.minLeaf;j++){if(ordered[j-1].x[f]===ordered[j].x[f])continue;const left=ordered.slice(0,j),right=ordered.slice(j),loss=sse(left)+sse(right);if(loss<bestLoss-1e-10){bestLoss=loss;best={f,threshold:(ordered[j-1].x[f]+ordered[j].x[f])/2,left,right};}}}
 if(!best)return {value};importance[best.f]+=parentLoss-bestLoss;return {value,feature:best.f,threshold:best.threshold,left:tree(best.left,depth+1),right:tree(best.right,depth+1)};}
 const trees=Array.from({length:config.trees},()=>tree(Array.from({length:samples.length},()=>samples[Math.floor(random()*samples.length)]),0));const total=importance.reduce((a,b)=>a+b,0);return {version:'nortex-rf-js-1',config,trees,importance:importance.map((v,i)=>({feature:FEATURES[i],value:total?v/total:0}))};
}
export function infer(model,x){return mean(model.trees.map(root=>{let n=root;while(n.left)n=x[n.feature]<=n.threshold?n.left:n.right;return n.value;}));}
export function score(actual,predicted){const errors=actual.map((v,i)=>predicted[i]-v);return {n:errors.length,mae:mean(errors.map(Math.abs)),rmse:Math.sqrt(mean(errors.map(x=>x*x))),bias:mean(errors)};}
export function experiment(rows,source){if(!source.startsWith('NASA POWER'))throw Error('Consulta primero datos reales de NASA POWER. No se entrena sobre la demo.');const {samples,sorted}=dataset(rows),training=samples.filter(s=>s.date<='2025-09-30'),testing=samples.filter(s=>s.date>='2025-10-01');if(training.length<120||testing.length<30)throw Error(`Datos insuficientes: ${training.length} muestras de entrenamiento y ${testing.length} de evaluación; mínimo 120/30.`);const model=train(training),pred=testing.map(s=>infer(model,s.x)),base=testing.map(s=>s.x[0]),actual=testing.map(s=>s.y),rf=score(actual,pred),baseline=score(actual,base);const finalX=features(sorted.slice(-7)),last=sorted.at(-1);return {version:'predict-2.0',source,target:'Temperatura máxima del aire del día siguiente, °C',horizon_days:1,model,training:{start:training[0].date,end:training.at(-1).date,n:training.length},evaluation:{start:testing[0].date,end:testing.at(-1).date,n:testing.length,rf,baseline,rf_better_mae:rf.mae<baseline.mae},excluded_windows:Math.max(0,sorted.length-7-samples.length),predictions:testing.map((s,i)=>({date:s.date,origin:s.origin,actual:s.y,rf:pred[i],baseline:base[i]})),scenario:finalX?{origin:last.date,date:new Date(Date.parse(last.date)+86400000).toISOString().slice(0,10),rf:infer(model,finalX),baseline:finalX[0]}:null,limits:['Modelo congelado al cierre de septiembre; evaluación de un paso con observaciones previas disponibles.','Un año y un punto no prueban generalización. No se ajustan hiperparámetros con octubre–diciembre.','Importancia por reducción de error en entrenamiento, no causal ni SHAP.','Sin intervalo de confianza calibrado. Escenario histórico; no pronóstico del tiempo actual.']};}
